        emon.Testport.assertEq(Oil.oilBlockStride(0), 5, "only the block base");
        emon.Testport.assertEq(Oil.oilBlockStride(Oil.ocBtype() + Oil.ocWdir()), 9, "kind and orientation group");
        emon.Testport.assertEq(Oil.oilLineStride(0), 6, "line confidence is optional");
        emon.Testport.assertEq(Oil.oilLineStride((Oil.ocLconf() + Oil.ocParas()) + Oil.ocBaseline()), 12, "confidence, paragraph and baseline");
        emon.Testport.assertEq(Oil.oilLineStride((Oil.ocRowmetrics() + Oil.ocQuad()) + Oil.ocAngle()), 18, "metrics, quad and signed angle");
        emon.Testport.assertEq(Oil.oilWordBase(0), 6, "word base only");
        emon.Testport.assertEq(Oil.oilWordBase((((Oil.ocWlang() + Oil.ocStyle()) + Oil.ocPsize()) + Oil.ocLexicon()) + Oil.ocWalts()), 11, "word groups include the word-alternative count");
